// dữ liệu tương đương và rẻ hơn (không cần gọi RPC lại).
export async function getOnChainHistory(
  _groupContractAddress: string
): Promise<OnChainHistoryEvent[]> {
  if (!IS_CONTRACT_CONFIGURED) return [];
  return [];
}
